      (@ImbalancedChen.p1SignedExitHistoryKeys.{u_1} α inst k states) fun (c : Prod.{0, u_1} Nat (List.{u_1} α)) =>
      @List.sum.{0} Real Real.instAdd Real.instZero
        (@List.map.{u_1, 0} (ImbalancedChen.FirstExitDepthState.{u_1} α) Real
          (@ImbalancedChen.p1SignedExitValue.{u_1} α h)
          (@List.filter.{u_1} (ImbalancedChen.FirstExitDepthState.{u_1} α)
            (fun (state : ImbalancedChen.FirstExitDepthState.{u_1} α) =>
              @Decidable.decide
                (@Eq.{u_1 + 1} (Prod.{0, u_1} Nat (List.{u_1} α))
                  (@ImbalancedChen.p1SignedExitHistoryKey.{u_1} α k state) c)
                (@instDecidableEqProd.{0, u_1} Nat (List.{u_1} α) instDecidableEqNat
